<?php

declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/src/includes/errors.php';
require_once dirname(__DIR__, 2) . '/src/includes/app.php';
require_once dirname(__DIR__, 2) . '/src/function/teams_surface_provider.php';
require_once dirname(__DIR__, 2) . '/src/function/api_workouts.php';
$idUsuario = stridebr_require_login();
if (!stridebr_teams_enabled()) stridebr_error_document(404);
require_once dirname(__DIR__, 2) . '/src/config/pg_config.php';
$ref = trim((string) ($_GET['id'] ?? ''));
$training = $ref !== '' ? stridebr_teams_surface_training($pdo, $idUsuario, $ref) : null;
if (!$training) stridebr_error_document(404);
$workout = stridebr_api_teams_workout_payload($pdo, $idUsuario, $training);
?>
<!doctype html><html lang="<?php echo stridebr_e(stridebr_html_lang()); ?>"><head><?php echo stridebr_ui_boot_script(); ?><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="<?php echo stridebr_e(stridebr_asset('/assets/css/style.css')); ?>"><link rel="stylesheet" href="<?php echo stridebr_e(stridebr_asset('/assets/css/institutional.css')); ?>"><link rel="stylesheet" href="<?php echo stridebr_e(stridebr_asset('/assets/css/ui-refresh.css')); ?>"><title><?php echo stridebr_e((string) $workout['title']); ?> | StrideBR</title></head><body><div class="container-fluid"><?php require dirname(__DIR__, 2) . '/src/layout/header.php'; ?><main class="main-content"><div class="institutional-shell"><header class="institutional-head"><div><span class="institutional-badge"><?php echo stridebr_e(stridebr_t('teams.institutional')); ?></span><h1><?php echo stridebr_e((string) $workout['title']); ?></h1><p><?php echo stridebr_e((string) $workout['institutional_context']['organization']['name']); ?> · <?php echo stridebr_e((string) $workout['institutional_context']['team']['name']); ?></p><div class="institutional-meta"><span><?php echo stridebr_e((string) $workout['date']); ?><?php echo $workout['time'] ? ' · ' . stridebr_e((string) $workout['time']) : ''; ?></span><?php if ($workout['planned_duration_s']): ?><span><?php echo (int) round((int) $workout['planned_duration_s'] / 60); ?> min</span><?php endif; ?><?php if ($workout['planned_distance_m']): ?><span><?php echo stridebr_e(number_format((float) $workout['planned_distance_m'] / 1000, 2, ',', '.')); ?> km</span><?php endif; ?></div></div><?php if (!empty($workout['capabilities']['can_start_session'])): ?><button class="primary-button" type="button" data-start-institutional="<?php echo stridebr_e($ref); ?>"><?php echo stridebr_e(stridebr_t('teams.start_training')); ?></button><?php endif; ?></header><section class="institutional-card"><h2><?php echo stridebr_e(stridebr_t('teams.structure')); ?></h2><div class="institutional-structure"><?php foreach ((array) ($workout['structure']['exercises'] ?? []) as $index => $step): ?><div class="institutional-step"><span class="institutional-step-index"><?php echo $index + 1; ?></span><div><strong><?php echo stridebr_e((string) $step['name']); ?></strong><div class="institutional-meta"><span><?php echo stridebr_e((string) $step['step_type']); ?></span><?php if ($step['duration_s']): ?><span><?php echo (int) round((int) $step['duration_s'] / 60); ?> min</span><?php endif; ?><?php if (!empty($step['distance'])): ?><span><?php echo stridebr_e((string) $step['distance']); ?></span><?php endif; ?></div></div></div><?php endforeach; ?></div></section><?php if (!empty($workout['institutional_context']['planning_block'])): ?><section class="institutional-card"><h2><?php echo stridebr_e(stridebr_t('teams.planning_block')); ?></h2><p><?php echo stridebr_e((string) $workout['institutional_context']['planning_block']['name']); ?></p></section><?php endif; ?></div></main></div><?php require dirname(__DIR__, 2) . '/src/layout/footer.php'; ?><script src="<?php echo stridebr_e(stridebr_asset('/assets/js/institutional.js')); ?>"></script></body></html>
